import{_ as a,o,c as l,aw as s}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Деплой","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common/deploy/vercel/deploy.md","filePath":"wiki/dev-commit/common/deploy/vercel/deploy.md"}'),t={name:"wiki/dev-commit/common/deploy/vercel/deploy.md"};function n(r,e,i,c,p,d){return o(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="деплои" tabindex="-1">Деплой <a class="header-anchor" href="#деплои" aria-label="Permalink to &quot;Деплой&quot;">​</a></h1><h2 id="_1-github-vercel-dashboard" tabindex="-1">1. GitHub + Vercel Dashboard <a class="header-anchor" href="#_1-github-vercel-dashboard" aria-label="Permalink to &quot;1. GitHub + Vercel Dashboard&quot;">​</a></h2><h3 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h3><ol><li>Загрузить проект на GitHub / GitLab / Bitbucket</li><li>Авторизоваться в Vercel и перейти на <em>&quot;Projects&quot;</em></li><li>Кнопка <em>&quot;Add New&quot;</em> -&gt; <em>&quot;Project&quot;</em></li><li>Секция <em>Import Git Repository</em> -&gt; Выбрать Git provider (GitHub / GitLab / Bitbucket) -&gt; Выбрать репозиторий -&gt; Import</li><li>Страница <em>New Project</em> -&gt; Указать настройки -&gt; <em>Deploy</em></li><li>Запустится процесс деплоя -&gt; Сообщение об успешном деплое -&gt; Кнопка &quot;Continue to Dashboard&quot;</li><li>При каждом push в main ветку репозитория, будет пересобираться проект</li></ol><h3 id="настроики-билда-шаг-5" tabindex="-1">Настройки билда (Шаг 5) <a class="header-anchor" href="#настроики-билда-шаг-5" aria-label="Permalink to &quot;Настройки билда (Шаг 5)&quot;">​</a></h3><ul><li><em>Build Command</em>: <code>npm run build</code></li><li><em>Output Directory</em>: <code>dist</code></li></ul><h2 id="_2-vercel-cli" tabindex="-1">2. Vercel CLI <a class="header-anchor" href="#_2-vercel-cli" aria-label="Permalink to &quot;2. Vercel CLI&quot;">​</a></h2><h3 id="команды" tabindex="-1">Команды <a class="header-anchor" href="#команды" aria-label="Permalink to &quot;Команды&quot;">​</a></h3><p>В корне проекта:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">npm</span><span style="color:#50A14F;"> i</span><span style="color:#986801;"> -g</span><span style="color:#50A14F;"> vercel</span></span>
<span class="line"><span style="color:#4078F2;">vercel</span><span style="color:#50A14F;"> login</span></span>
<span class="line"><span style="color:#4078F2;">vercel</span></span></code></pre></div><p>Для продакшн-деплоя:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">vercel</span><span style="color:#986801;"> --prod</span></span></code></pre></div><hr><h2 id="важное-для-spa-роутинга-react-router" tabindex="-1">Важное для SPA-роутинга (React Router) <a class="header-anchor" href="#важное-для-spa-роутинга-react-router" aria-label="Permalink to &quot;Важное для SPA-роутинга (React Router)&quot;">​</a></h2><p>Если у тебя client-side routes (например, <code>/about</code>), при прямом открытии URL может быть 404 — нужно правило “всё на <code>index.html</code>”.</p><h3 id="как-сделать-на-vercel" tabindex="-1">Как сделать на Vercel <a class="header-anchor" href="#как-сделать-на-vercel" aria-label="Permalink to &quot;Как сделать на Vercel&quot;">​</a></h3><ul><li>Обычно Vercel сам справляется для многих шаблонов, но если нет — добавь <code>vercel.json</code>:</li></ul><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">{</span></span>
<span class="line"><span style="color:#E45649;">  &quot;rewrites&quot;</span><span style="color:#383A42;">: [{ </span><span style="color:#E45649;">&quot;source&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;/(.*)&quot;</span><span style="color:#383A42;">, </span><span style="color:#E45649;">&quot;destination&quot;</span><span style="color:#383A42;">: </span><span style="color:#50A14F;">&quot;/&quot;</span><span style="color:#383A42;"> }]</span></span>
<span class="line"><span style="color:#383A42;">}</span></span></code></pre></div><p>Файл кладётся <strong>в корень</strong> проекта, рядом с <code>package.json</code></p><hr><h2 id="переменные-окружения" tabindex="-1">Переменные окружения <a class="header-anchor" href="#переменные-окружения" aria-label="Permalink to &quot;Переменные окружения&quot;">​</a></h2><ul><li>В Vercel Project → <strong>Settings → Environment Variables</strong></li><li>После изменения env обычно нужен <strong>Redeploy</strong>.</li></ul>`,22)])])}const m=a(t,[["render",n]]);export{h as __pageData,m as default};
